def check_domain(x, y):
    x_valid = (isinstance(x, (int, float)) and 0 <= x <= 500)
    y_valid = (y in ['PASS', 'FLAGGED', 'PENDING'])
    return {
        'x': {'value': x, 'in_domain': x_valid},
        'y': {'value': y, 'in_domain': y_valid},
        'overall_pass': x_valid and y_valid
    }
